$records=series_records();foreach($records as $record)if(isset($record['slug'],$record['title']))$builtIn[$record['slug']]=$record['title'];$slug=(string)($_GET['series']??$_POST['series']??array_key_first($builtIn));if(!isset($builtIn[$slug]))$slug=array_key_first($builtIn);$notice=(string)($_GET['notice']??'');$error='';
$seriesBySlug=[];foreach($records as $record)$seriesBySlug[$record['slug']]=$record;
