?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin panel | RankSetu</title><style>:root{--navy:#16233f;--maroon:#9c3b2e;--paper:#efece2;--card:#f8f6ee;--muted:#625e50;--line:#cfc7ac;--gold:#a97a24;--green:#286447}*{box-sizing:border-box}body{margin:0;background:var(--paper);font-family:Arial;color:#1c1a15}header{background:var(--navy);border-bottom:3px solid var(--gold);padding:18px 5%;display:flex;justify-content:space-between;align-items:center}.brand{font:700 1.5rem Georgia;color:#fff}.nav a{color:#f5ead2;text-decoration:none;margin-left:18px;font-size:.9rem}.wrap{width:min(1180px,calc(100% - 40px));margin:auto;padding:38px 0}h1,h2{font-family:Georgia;color:var(--navy)}h1{font-size:2.6rem;margin:0 0 8px}.muted{color:var(--muted)}.stats,.columns{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat,.panel,.question{background:var(--card);border:1px solid var(--line);padding:20px}.stat strong{display:block;color:var(--maroon);font:700 1.8rem Georgia}.stat span{color:var(--muted);font-size:.8rem}.panel{margin-top:20px}.columns{grid-template-columns:260px 1fr;margin-top:20px}.series-list{display:grid;gap:7px}.series-link{padding:12px;background:#fffdf7;border:1px solid var(--line);color:var(--navy);text-decoration:none}.series-link.active{border-color:var(--maroon);border-left:4px solid var(--maroon)}label{display:block;font-size:.8rem;font-weight:700;margin:12px 0 5px}input,textarea,select{width:100%;padding:10px;border:1px solid var(--line);background:#fffdf7;font:inherit}textarea{min-height:65px;resize:vertical}.btn{display:inline-block;background:var(--maroon);color:#fff;border:0;padding:10px 14px;font-weight:700;text-decoration:none;cursor:pointer;font-size:.85rem}.outline{background:transparent;border:1px solid var(--maroon);color:var(--maroon)}.danger{background:#70251c}.notice,.error{padding:12px;margin:14px 0}.notice{background:#e0f0e6;color:#174b32}.error{background:#f7ded8;color:#70251c}.questions{display:grid;gap:12px}.question{padding:20px}.question-head{display:flex;justify-content:space-between;gap:15px}.question h3{font:600 1.15rem Georgia;color:var(--navy);margin:8px 0}.tag{color:var(--maroon);font-size:.78rem;font-weight:700;text-transform:uppercase}.options{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:14px 0}.option{padding:9px;background:#fffdf7;border:1px solid var(--line);font-size:.88rem}.correct{background:#e0f0e6;border-color:var(--green)}.actions{display:flex;gap:8px;justify-content:flex-end;border-top:1px solid var(--line);padding-top:14px}@media(max-width:800px){.stats,.columns{grid-template-columns:1fr}.options{grid-template-columns:1fr}.wrap{padding:28px 0}.question-head{display:block}.actions{justify-content:start}}
</style></head><body><header><div class="brand">RankSetu Admin</div><nav class="nav"><a href="admin-questions.php?series=<?=e($slug)?>">Question manager</a><a href="index.php">View site</a><a href="logout.php">Log out</a></nav></header><main class="wrap"><h1>Control centre</h1><p class="muted">Manage series, questions, users and performance.</p><?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><section class="stats"><div class="stat"><strong><?=count($users)?></strong><span>users</span></div><div class="stat"><strong><?=$orders?></strong><span>orders</span></div><div class="stat"><strong><?=$attempts?></strong><span>attempts</span></div><div class="stat"><strong><?=$average?>%</strong><span>average score</span></div></section><section class="panel"><h2>Create test series</h2><form method="post"><input type="hidden" name="action" value="create_series"><div class="columns"><div><label>Title</label><input name="title" required placeholder="UPSC Prelims"></div><div><label>Slug</label><input name="slug" placeholder="upsc-prelims"></div></div><label>Stage</label><input name="stage" placeholder="Prelims"><label>Description</label><textarea name="description"></textarea><button class="btn" type="submit">Create inactive series</button></form></section><section class="columns"><aside class="panel"><h2>Series</h2><div class="series-list"><?php foreach($builtIn as $key=>$name):?><a class="series-link <?=$key===$slug?'active':''?>" href="admin.php?series=<?=e($key)?>"><?=e($name)?></a><?php endforeach;?></div></aside><section class="panel"><h2>Edit series</h2><form method="post"><input type="hidden" name="action" value="update_series"><label>Title</label><input name="title" value="<?=e($selectedRecord['title'])?>" required><label>Stage</label><input name="stage" value="<?=e($selectedRecord['stage'])?>"><label>Description</label><textarea name="description"><?=e($selectedRecord['description'])?></textarea><label><input type="checkbox" name="active" style="width:auto" <?=!empty($selectedRecord['active'])?'checked':''?>> Publish on homepage</label><button class="btn" type="submit">Update series</button></form></section></section><section class="panel"><div style="display:flex;justify-content:space-between;gap:15px;align-items:center"><div><h2>Questions for <?=e($selectedRecord['title'])?></h2><p class="muted"><?=count($test['questions']??[])?> / 10 questions &bull; <?=$test['duration_minutes']??10?> minutes</p></div><a class="btn" href="admin-question.php?series=<?=e($slug)?>">Add question</a></div><?php if(empty($test['questions'])):?><p class="muted">No questions yet.</p><?php else:?><div class="questions"><?php foreach($test['questions'] as $index=>$question):?><article class="question"><div class="question-head"><div><div class="tag">Question <?=$index+1?> &bull; <?=e($question['topic'])?></div><h3><?=e($question['q'])?></h3></div><div class="muted">Correct: <?=e($question['options'][$question['answer']]??'')?></div></div><div class="options"><?php foreach($question['options'] as $optionIndex=>$option):?><div class="option <?=$optionIndex===(int)$question['answer']?'correct':''?>"><strong><?=chr(65+$optionIndex)?>.</strong> <?=e($option)?></div><?php endforeach;?></div><div class="actions"><a class="btn outline" href="admin-question.php?series=<?=e($slug)?>&index=<?=$index?>">Edit question</a><form method="post" onsubmit="return confirm('Delete this question?')"><input type="hidden" name="action" value="delete_question"><input type="hidden" name="series" value="<?=e($slug)?>"><input type="hidden" name="index" value="<?=$index?>"><button class="btn danger" type="submit">Delete question</button></form></div></article><?php endforeach;?></div><?php endif;?></section></main></body></html>

